    def length_of_intersection(interval1, interval2):
        start = max(interval1[0], interval2[0])
        end = min(interval1[1], interval2[1])
        return end - start + 1 if start <= end else 0

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    length = length_of_intersection(interval1, interval2)

    if length > 0 and is_prime(length):
        return "YES"
    else:
        return "NO"

